#include <iostream>
#include <print>
#include <string>
#include <utility>
#include <vector>

struct Message {
    static inline int copies = 0;
    static inline int moves = 0;
    std::string text;

    explicit Message(std::string t) : text(std::move(t)) {}
    Message(const Message &o) : text(o.text) {
        ++copies;
    }
    Message(Message &&o) noexcept : text(std::move(o.text)) {
        ++moves;
    }
};

class Mailbox {
public:
    Mailbox() {
        box_.reserve(1000);
    }

    void add(const Message &m) {
        box_.push_back(m);
    }

    void add(Message &&m) {
        box_.push_back(std::move(m));
    }

    void list() const {
        std::string s;
        for (const Message &m : box_) {
            s += (s.empty() ? "" : " ") + m.text;
        }
        std::println("{}", s);
    }

private:
    std::vector<Message> box_;
};

int main() {
    Mailbox mailbox;
    std::string command;
    while (std::cin >> command) {
        if (command == "list") {
            mailbox.list();
        } else if (command == "stats") {
            std::println("копий {}, перемещений {}", Message::copies, Message::moves);
        } else {
            std::string text;
            std::cin >> text;
            if (command == "send") {
                mailbox.add(Message(text));
            } else if (command == "keep") {
                const Message m(text);
                mailbox.add(m);
                std::println("у отправителя: {}", m.text);
            } else {
                Message m(text);
                mailbox.add(std::move(m));
            }
        }
    }
    return 0;
}

