#include <iostream>
#include <print>
#include <string>
#include <string_view>
#include <utility>
#include <vector>

class Builder {
public:
    static inline int copies = 0;
    static inline int moves = 0;

    Builder &add(std::string_view s) & {
        append(s);
        return *this;
    }

    Builder &&add(std::string_view s) && {
        append(s);
        return std::move(*this);
    }

    std::string build() const & {
        ++copies;
        return text_;
    }

    std::string build() && {
        ++moves;
        return std::move(text_);
    }

private:
    void append(std::string_view s) {
        if (!text_.empty()) {
            text_ += ' ';
        }
        text_ += s;
    }

    std::string text_;
};

std::vector<std::string> read_words(std::istream &in) {
    std::size_t n;
    in >> n;
    std::vector<std::string> words(n);
    for (std::string &w : words) {
        in >> w;
    }
    return words;
}

int main() {
    std::string command;
    while (std::cin >> command) {
        if (command == "once") {
            std::string a, b, c;
            std::cin >> a >> b >> c;
            std::println("результат: {}", Builder().add(a).add(b).add(c).build());
        } else if (command == "named") {
            Builder b;
            for (const std::string &w : read_words(std::cin)) {
                b.add(w);
            }
            std::println("результат: {}", b.build());
            std::println("результат: {}", b.build());
        } else if (command == "take") {
            Builder b;
            for (const std::string &w : read_words(std::cin)) {
                b.add(w);
            }
            std::println("результат: {}", std::move(b).build());
        } else {
            std::println("копий {}, перемещений {}", Builder::copies, Builder::moves);
        }
    }
    return 0;
}

